可以发现除了⼥神的睿智外，合成出的颜⾊取决于左侧，所以 个⼤结晶的颜⾊等于第 , 个碎⽚的颜⾊，⼥神的睿
智的颜⾊取决于第 , 个碎⽚的颜⾊和与其同⾊的碎⽚的数量。
#include &lt;bits/stdc++.h&gt;using namespace std;int T;char s[10];int main()&#123;	scanf(&quot;%d&quot;,&amp;T);	while(T--)&#123;		scanf(&quot;%s&quot;,s+1);		int R=0,G=0,B=0;		for(int i=1;i&lt;=8;i++)&#123;			if(s[i]==&#x27;R&#x27;)R++;			if(s[i]==&#x27;G&#x27;)G++;			if(s[i]==&#x27;B&#x27;)B++;		&#125;		if(s[1]==s[5])&#123;			cout&lt;&lt;s[1]&lt;&lt;endl;		&#125;else&#123;			int x,y;			if(s[1]==&#x27;R&#x27;)&#123;				x=R;			&#125;else if(s[1]==&#x27;G&#x27;)&#123;				x=G;			&#125;else&#123;				x=B;			&#125;			if(s[5]==&#x27;R&#x27;)&#123;				y=R;			&#125;else if(s[5]==&#x27;G&#x27;)&#123;				y=G;			&#125;else&#123;				y=B;			&#125;			if(x==y)&#123;				cout&lt;&lt;&quot;N\n&quot;;			&#125;else if(x&gt;y)&#123;				cout&lt;&lt;s[1]&lt;&lt;endl;			&#125;else&#123;				cout&lt;&lt;s[5]&lt;&lt;endl;			&#125;		&#125;	&#125;	return 0;&#125;

