3 Legend有⼀个 个结点的有根树，你需要从1号结点⾛到任意⼀个叶⼦节点，每天你有 pi&#x2F;15的可能性可以向任意⼀个⼉⼦节点⾛⼀步（ i为你当前所在的节点编号），询问你期望最多可以在这颗树上⾛多久。
简单分析⼀下⼀下题意就是每个点有⼀个期望的停留时间（可以⽤分数类来维护），然后我们只⽤找到⼀条期望时
间之和最⻓的⼀端为根节点的链即可
#include&lt;bits/stdc++.h&gt;#define M 200005using namespace std;struct E&#123;	int to,nx;&#125;edge[M];int tot,head[M];void Addedge(int a,int b)&#123;	edge[++tot].to=b;	edge[tot].nx=head[a];	head[a]=tot;&#125;int A[M];int fa[M];long long gcd(long long a,long long b)&#123;	if(!b)return a;	return gcd(b,a%b);&#125;long long lcm(long long a,long long b)&#123;	return a/gcd(a,b)*b;&#125;struct node&#123;	long long a,b;	bool operator &lt;(const node &amp;_)const&#123;		long long tmp=lcm(b,_.b);		return a*(tmp/b)&lt;_.a*(tmp/_.b);	&#125;	node operator +(const node &amp;_)const&#123;		node res;		res.b=lcm(b,_.b);		res.a=a*(res.b/b)+_.a*(res.b/_.b);		if(res.a==0)return (node)&#123;0,1&#125;;		long long g=gcd(res.a,res.b);		res.a/=g;		res.b/=g;		return res;	&#125;&#125;dp[M];void dfs(int now)&#123;	dp[now]=(node)&#123;0,1&#125;;	for(int i=head[now];i;i=edge[i].nx)&#123;		int nxt=edge[i].to;		if(nxt==fa[now])continue;		fa[nxt]=now;		dfs(nxt);		dp[now]=max(dp[now],dp[nxt]);	&#125;	dp[now]=dp[now]+(node)&#123;15,A[now]&#125;;&#125;int main()&#123;	int T;	scanf(&quot;%d&quot;,&amp;T);	while(T--)&#123;		int n;		scanf(&quot;%d&quot;,&amp;n);		tot=0;for(int i=1;i&lt;=n;i++)head[i]=0;		for(int i=1;i&lt;n;i++)&#123;			int a,b;			scanf(&quot;%d%d&quot;,&amp;a,&amp;b);			Addedge(a,b);			Addedge(b,a);		&#125;		for(int i=1;i&lt;=n;i++)scanf(&quot;%d&quot;,&amp;A[i]);		dfs(1);		printf(&quot;%lld/%lld\n&quot;,dp[1].a,dp[1].b);	&#125;	return 0;&#125;

4 data考虑集合加入数字 gcd 如果变化至少减半，所以数列所有区间的 gcd本质不同的个数只有 O(n log n) 个。
考虑对答案做简单容斥，计算有多少个合法方案不包含 i 。只需计算出前缀 1 · · ·i−1 中选出若干区间符合条件的方案数、后缀 i + 1 · · · n 中选出若干区间符合条件的方案数。考虑对每种 gcd 分别求解，以前缀为例，考虑所有右端点在 i − 1、gcd为当前考虑的 gcd 的区间，其左端点连续，构成了某个区间 [l, r]。这样计数的 dp 就可以用线段树来优化转移，复杂度和此时的 (l, r) 数对个数相关，由前述结论总复杂度均摊是 O(n log2 a) 的。
#include &lt;bits/stdc++.h&gt;using namespace std;typedef long long ll;struct Info&#123;    int id, p, _p;    Info(int id = 0, int p = 0, int _p = 0): id(id), p(p), _p(_p)&#123;&#125;&#125;;const int MAXN = 100000+5;const ll mod = 998244353;int n, cnt;int a[MAXN];int lx[MAXN][18], rx[MAXN][18];ll lsum[MAXN&lt;&lt;2], lsum2[MAXN&lt;&lt;2], rsum[MAXN&lt;&lt;2], rsum2[MAXN&lt;&lt;2];ll ans[MAXN], b[MAXN];vector&lt;Info&gt; lv[MAXN*10], rv[MAXN*10];map&lt;int, int&gt; mp;int gcd(int a, int b)&#123;    return b ? gcd(b, a%b) : a;&#125;int find(int g)&#123;    if(mp.find(g) == mp.end()) mp[g] = ++cnt;    return mp[g];&#125;void push_up(int x)&#123;    int ls = x&lt;&lt;1, rs = x&lt;&lt;1|1;    lsum[x] = lsum[ls] + lsum[rs];    rsum[x] = rsum[ls] + rsum[rs];    lsum2[x] = lsum2[ls] + lsum2[rs];    rsum2[x] = rsum2[ls] + rsum2[rs];&#125;void build(int x, int l, int r)&#123;    if(l == r)&#123;        if(l == 0)&#123;            lsum[x] = 1;        &#125;        if(r == n+1)&#123;            rsum[x] = 1;        &#125;        return;    &#125;    int mid = (l+r)/2;    build(x&lt;&lt;1, l, mid);    build(x&lt;&lt;1|1, mid+1, r);    push_up(x);&#125;ll qlsum(int x, int l, int r, int L, int R)&#123;    if(L &lt;= l &amp;&amp; r &lt;= R)&#123;        return lsum[x];    &#125;    int mid = (l+r)/2;    ll res = 0;    if(L &lt;= mid)&#123;        res += qlsum(x&lt;&lt;1, l, mid, L, R);    &#125;    if(R &gt; mid)&#123;        res += qlsum(x&lt;&lt;1|1, mid+1, r, L, R);    &#125;    return res;&#125;ll qlsum2(int x, int l, int r, int L, int R)&#123;    if(L &lt;= l &amp;&amp; r &lt;= R)&#123;        return lsum2[x];    &#125;    int mid = (l+r)/2;    ll res = 0;    if(L &lt;= mid)&#123;        res += qlsum2(x&lt;&lt;1, l, mid, L, R);    &#125;    if(R &gt; mid)&#123;        res += qlsum2(x&lt;&lt;1|1, mid+1, r, L, R);    &#125;    return res;&#125;void updl(int x, int l, int r, int p, ll v)&#123;    if(l == r)&#123;        lsum[x] = v;        lsum2[x] = v*(n-p)%mod;        return;    &#125;    int mid = (l+r)/2;    if(p &lt;= mid)&#123;        updl(x&lt;&lt;1, l, mid, p, v);    &#125;else&#123;        updl(x&lt;&lt;1|1, mid+1, r, p, v);    &#125;    lsum[x] = lsum[x&lt;&lt;1] + lsum[x&lt;&lt;1|1];    lsum2[x] = lsum2[x&lt;&lt;1] + lsum2[x&lt;&lt;1|1];&#125;ll qrsum(int x, int l, int r, int L, int R)&#123;    if(L &lt;= l &amp;&amp; r &lt;= R)&#123;        return rsum[x];    &#125;    int mid = (l+r)/2;    ll res = 0;    if(L &lt;= mid)&#123;        res += qrsum(x&lt;&lt;1, l, mid, L, R);    &#125;    if(R &gt; mid)&#123;        res += qrsum(x&lt;&lt;1|1, mid+1, r, L, R);    &#125;    return res;&#125;ll qrsum2(int x, int l, int r, int L, int R)&#123;    if(L &lt;= l &amp;&amp; r &lt;= R)&#123;        return rsum2[x];    &#125;    int mid = (l+r)/2;    ll res = 0;    if(L &lt;= mid)&#123;        res += qrsum2(x&lt;&lt;1, l, mid, L, R);    &#125;    if(R &gt; mid)&#123;        res += qrsum2(x&lt;&lt;1|1, mid+1, r, L, R);    &#125;    return res;&#125;void updr(int x, int l, int r, int p, ll v)&#123;    if(l == r)&#123;        rsum[x] = v;        rsum2[x] = v*p%mod;        return;    &#125;    int mid = (l+r)/2;    if(p &lt;= mid)&#123;        updr(x&lt;&lt;1, l, mid, p, v);    &#125;else&#123;        updr(x&lt;&lt;1|1, mid+1, r, p, v);    &#125;    rsum[x] = rsum[x&lt;&lt;1] + rsum[x&lt;&lt;1|1];    rsum2[x] = rsum2[x&lt;&lt;1] + rsum2[x&lt;&lt;1|1];&#125;void add(int l, int r, ll v)&#123;    b[l] += v;    b[r+1] -= v;&#125;int main()&#123;    cin &gt;&gt; n;    for(int i = 1; i &lt;= n; i++)cin &gt;&gt; a[i];    for(int i = 1; i &lt;= n; i++)&#123;        lx[i][0] = a[i];        rx[i][0] = a[i];    &#125;    for(int j = 1; j &lt; 18; j++)&#123;        for(int i = 1; i &lt;= n; i++)&#123;            if(i-(1&lt;&lt;j)+1 &gt;= 1)&#123;                lx[i][j] = gcd(lx[i][j-1], lx[i-(1&lt;&lt;(j-1))][j-1]);            &#125;            if(i+(1&lt;&lt;j)-1 &lt;= n)&#123;                rx[i][j] = gcd(rx[i][j-1], rx[i+(1&lt;&lt;(j-1))][j-1]);            &#125;        &#125;    &#125;    for(int i = 1; i &lt;= n; i++)&#123;        int p = i, g = a[i];        while(p &gt;= 1)&#123;            int _p = p;            for(int j = 17; j &gt;= 0; j--)&#123;                if(p-(1&lt;&lt;j)+1 &gt;= 1 &amp;&amp; gcd(g, lx[p][j]) == g)&#123;                    p = p - (1&lt;&lt;j);                &#125;            &#125;            lv[find(g)].push_back(Info(i, p+1, _p));            g = gcd(g, a[p]);        &#125;    &#125;    for(int i = 1; i &lt;= n; i++)&#123;        int p = i, g = a[i];        while(p &lt;= n)&#123;            int _p = p;            for(int j = 17; j &gt;= 0; j--)&#123;                if(p+(1&lt;&lt;j)-1 &lt;= n &amp;&amp; gcd(g, rx[p][j]) == g)&#123;                    p = p + (1&lt;&lt;j);                &#125;            &#125;            rv[find(g)].push_back(Info(i, p-1, _p));            g = gcd(g, a[p]);        &#125;    &#125;    build(1, 0, n+1);    for(auto bp : mp)&#123;        int g = bp.first, id = bp.second;        sort(lv[id].begin(), lv[id].end(), [&amp;](Info a, Info b)&#123;            return a.id &lt; b.id;        &#125;);        ll sum = 1;        vector&lt;int&gt; vec;        for(auto info : lv[id])&#123;            int x = info.id, p = info.p, _p = info._p;            vec.push_back(x);            ll res = qlsum(1, 0, n+1, 0, p-1)*(_p-p+1) + qlsum2(1, 0, n+1, p, _p) - qlsum(1, 0, n+1, p, _p)*(n-_p);            res = (res % mod + mod) % mod;            sum += res;            updl(1, 0, n+1, x, res);        &#125;        sum %= mod;        sort(rv[id].begin(), rv[id].end(), [&amp;](Info a, Info b)&#123;            return a.id &gt; b.id;        &#125;);        for(auto info : rv[id])&#123;            int x = info.id, p = info.p, _p = info._p;            vec.push_back(x);            ll res = qrsum(1, 0, n+1, p+1, n+1)*(p-_p+1) + qrsum2(1, 0, n+1, _p, p) - qrsum(1, 0, n+1, _p, p)*_p;            res = (res % mod + mod) % mod;            updr(1, 0, n+1, x, res);        &#125;        sort(vec.begin(), vec.end());        vec.erase(unique(vec.begin(), vec.end()), vec.end());        int x = 0;        for(auto _x : vec)&#123;            ll tmp = (qlsum(1, 0, n+1, 0, _x-1)%mod)*(qrsum(1, 0, n+1, _x+1, n+1)%mod)%mod;            ans[_x] += sum-tmp;            if(_x - x &gt; 1)&#123;                add(x+1, _x-1, (sum - (qlsum(1, 0, n+1, 0, x)%mod)*(qrsum(1, 0, n+1, _x, n+1)%mod))%mod);            &#125;            x = _x;        &#125;        if(x &lt; n)&#123;            add(x+1, n, sum - qlsum(1, 0, n+1, 0, x));        &#125;        for(auto info : lv[id])&#123;            int x = info.id;            updl(1, 0, n+1, x, 0);        &#125;        for(auto info : rv[id])&#123;            int x = info.id;            updr(1, 0, n+1, x, 0);        &#125;    &#125;    for(int i = 1; i &lt;= n; i++)&#123;        b[i] += b[i-1];        ans[i] += b[i];        ans[i] = (ans[i] % mod + mod) % mod;        printf(&quot;%d\n&quot;, ans[i]);    &#125;    return 0;

5 dream⾸先看到 的数据范围很⼩，我们可以联想到可以⽤状态压缩的⽅式来表示怪物的存活情况。
然后对于⼀开始的⽣命值贷款这个机制，你可以这样想，你可以直接忽略⽣命值&lt;&#x3D;0 ⻆⾊就会死亡这个限
制，然后把怪物的攻击看成扣⾦币，这样算出⼀个最⼤⾦币收益的⽅案，其实就是最终的答案了。（因为你知道了
这种情况下的⽅案之后，你就知道了会受到多少怪物的攻击，那你⼀开始贷款那么多买⾎量就可以了）
然后可以设⽴状态dp[i][j][k] 表示当主⻆在点 (i,j) ，怪物的存活状态⽤⼆进制表示为k 时，主⻆最多能获得多少⾦
币，然后我们枚举在当前状态下可以进⾏的操作之后就可以得到他的后继状态。
接着我们发现，如果我们把 （i，j,  k)  看成是⼀个抽象点，把这些操作都看成是单项边，边权就是做这个操作所能获得的⾦币（这⾥有可能是负数，就是失去⾦币）。然后我们就得到了⼀张有权的有向图。那么我们只要做⼀遍单源的最⻓路就可以找到我们最终的答案。因为只有消灭怪物的时候⾦币才会变多（也就是正权边），所以这张图不会有正环，故我们直接使⽤传统的最⻓路算法即可。
#include&lt;bits/stdc++.h&gt;#define M 55using namespace std;struct data&#123;    int x,y,val,d,len;&#125;A[M];int mp[M][M];int dp[M][M][1&lt;&lt;10];int cost[M][M][1&lt;&lt;10];int n,m,K,lim,I;void Init()&#123;    memset(cost,0,sizeof(cost));    for(int chs=0;chs&lt;=I;chs++)&#123;        for(int i=1;i&lt;=n;i++)&#123;            for(int j=1;j&lt;=m;j++)&#123;                for(int k=1;k&lt;=K;k++)&#123;                    if((1&lt;&lt;(k-1))&amp;chs)continue;                    int d=abs(i-A[k].x)+abs(j-A[k].y);                    if(d&lt;=A[k].len)cost[i][j][chs]+=A[k].d;                &#125;            &#125;        &#125;    &#125;&#125;bool done[M][M];struct node&#123;    int x,y,val;    bool operator &lt;(const node &amp;_)const&#123;        return val&lt;_.val;    &#125;&#125;;int ans;int xr[]=&#123;0,-1,0,1&#125;;int yr[]=&#123;1,0,-1,0&#125;;bool check(int x,int y)&#123;    return 1&lt;=x&amp;&amp;x&lt;=n&amp;&amp;1&lt;=y&amp;&amp;y&lt;=m;&#125;void check_max(int &amp;x,int y)&#123;    if(x&lt;y)x=y;&#125;void Solve(int chs)&#123;    memset(done,0,sizeof(done));    priority_queue&lt;node&gt;Q;    for(int i=1;i&lt;=n;i++)for(int j=1;j&lt;=m;j++)&#123;        if(dp[i][j][chs]&gt;-1e8)&#123;            Q.push((node)&#123;i,j,dp[i][j][chs]&#125;);        &#125;    &#125;    while(!Q.empty())&#123;        node now=Q.top();Q.pop();        if(done[now.x][now.y])continue;        done[now.x][now.y]=true;        ans=max(ans,dp[now.x][now.y][chs]);        for(int op=0;op&lt;4;op++)&#123;            int pass=0,tot_val=0;            for(int i=1;i&lt;=lim;i++)&#123;                node nxt=now;                nxt.x+=xr[op]*i;                nxt.y+=yr[op]*i;                if(!check(nxt.x,nxt.y))break;                if(mp[nxt.x][nxt.y]!=0&amp;&amp;!((1&lt;&lt;(mp[nxt.x][nxt.y]-1))&amp;chs))&#123;                    pass|=1&lt;&lt;(mp[nxt.x][nxt.y]-1);                    tot_val+=A[mp[nxt.x][nxt.y]].val;                &#125;else if(!pass)&#123;                    int nxt_dp=dp[now.x][now.y][chs]-cost[nxt.x][nxt.y][chs];                    if(dp[nxt.x][nxt.y][chs]&lt;nxt_dp)&#123;                        dp[nxt.x][nxt.y][chs]=nxt_dp;                        Q.push((node)&#123;nxt.x,nxt.y,nxt_dp&#125;);                    &#125;                &#125;else &#123;                    check_max(dp[nxt.x][nxt.y][chs|pass],dp[now.x][now.y][chs]+tot_val-cost[nxt.x][nxt.y][chs|pass]);                &#125;            &#125;        &#125;    &#125;&#125;int main()&#123;    int T;    scanf(&quot;%d&quot;,&amp;T);    while(T--)&#123;        ans=0;        for(int i=0;i&lt;M;i++)for(int j=0;j&lt;M;j++)for(int k=0;k&lt;(1&lt;&lt;10);k++)dp[i][j][k]=-1e9;        memset(mp,0,sizeof(mp));        scanf(&quot;%d%d%d&quot;,&amp;n,&amp;m,&amp;K);        scanf(&quot;%d&quot;,&amp;lim);        for(int i=1;i&lt;=K;i++)&#123;            scanf(&quot;%d%d%d%d%d&quot;,&amp;A[i].x,&amp;A[i].y,&amp;A[i].val,&amp;A[i].d,&amp;A[i].len);            mp[A[i].x][A[i].y]=i;        &#125;        int sx,sy;        scanf(&quot;%d%d&quot;,&amp;sx,&amp;sy);        dp[sx][sy][0]=0;        I=1&lt;&lt;K;I--;        Init();        for(int chs=0;chs&lt;=I;chs++)&#123;            Solve(chs);        &#125;        printf(&quot;%d\n&quot;,ans);    &#125;    return 0;&#125;

6 graph考虑判断两个点是否在任意两张图上都互相联通，可以转换成看两个点在每⼀张图中并查集所在集合的根是否相
同。如何快速的判断两个集合相等，我们可以对这个集合进⾏哈希。给每⼀张图的每⼀个点随机⼀个long long范围内的数字作为哈希值，然后将所有点的哈希值求和（或者做异或之类的操作），作为集合的哈希值。
判断两个集合是否相等，只需要看两个集合的哈希值是否相等即可。于是我们只需要维护每⼀张图的并查集，同时对于每⼀个点，维护其所在集合的哈希值。由于不同的合并对于不同的点对之间的影响是不同的，所以在合并并查集的时候我们还需要启发式合并，以动态修改待合并点的哈希值。最后我们只需要通过哈希表&#x2F;map来统计总共有多少个点对的哈希值相同，这个答案即为所求在任意两张图上都互相联通的点对数量。
